    52	int ares_parse_aaaa_reply(const unsigned char *abuf, int alen,
    53	                          struct hostent **host, struct ares_addr6ttl *addrttls,
    54	                          int *naddrttls)
    55	{
    56	  struct ares_addrinfo ai;
    57	  struct ares_addrinfo_node *next;
    58	  struct ares_addrinfo_cname *next_cname;
    59	  char **aliases = NULL;
    60	  char *question_hostname = NULL;
    61	  struct hostent *hostent = NULL;
    62	  struct ares_in6_addr *addrs = NULL;
    63	  int naliases = 0, naddrs = 0, alias = 0, i;
    64	  int cname_ttl = INT_MAX;
    65	  int status;
    66	
    67	  memset(&ai, 0, sizeof(ai));
    68	
    69	  status = ares__parse_into_addrinfo2(abuf, alen, &question_hostname, &ai);
    70	  if (status != ARES_SUCCESS)
    71	    {
    72	      ares_free(question_hostname);
    73	
    74	      if (naddrttls)
    75	        {
    76	          *naddrttls = naddrs;
    77	        }
    78	
    79	      return status;
    80	    }
    81	
    82	  hostent = ares_malloc(sizeof(struct hostent));
    83	  if (!hostent)
    84	    {
    85	      goto enomem;
    86	    }
    87	
    88	  next = ai.nodes;
    89	  while (next)
    90	    {
    91	      ++naddrs;
    92	      next = next->ai_next;
    93	    }
    94	
    95	  next_cname = ai.cnames;
    96	  while (next_cname)
    97	    {
    98	      if(next_cname->alias)
    99	        ++naliases;
   100	      next_cname = next_cname->next;
   101	    }
   102	
   103	  aliases = ares_malloc((naliases + 1) * sizeof(char *));
   104	  if (!aliases)
   105	    {
   106	      goto enomem;
   107	    }
   108	
   109	  if (naliases)
   110	    {
   111	      next_cname = ai.cnames;
   112	      while (next_cname)
   113	        {
   114	          if(next_cname->alias)
   115	            aliases[alias++] = strdup(next_cname->alias);
   116	          if(next_cname->ttl < cname_ttl)
   117	            cname_ttl = next_cname->ttl;
   118	          next_cname = next_cname->next;
   119	        }
   120	    }
   121	
   122	  aliases[alias] = NULL;
   123	
   124	  hostent->h_addr_list = ares_malloc((naddrs + 1) * sizeof(char *));
   125	  if (!hostent->h_addr_list)
   126	    {
   127	      goto enomem;
   128	    }
   129	
   130	  if (ai.cnames)
   131	    {
   132	      hostent->h_name = strdup(ai.cnames->name);
   133	      ares_free(question_hostname);
   134	    }
   135	  else
   136	    {
   137	      hostent->h_name = question_hostname;
   138	    }
   139	
   140	  hostent->h_aliases = aliases;
   141	  hostent->h_addrtype = AF_INET6;
   142	  hostent->h_length = sizeof(struct ares_in6_addr);
   143	
   144	  if (naddrs)
   145	    {
   146	      addrs = ares_malloc(naddrs * sizeof(struct ares_in6_addr));
   147	      if (!addrs)
   148	        {
   149	          goto enomem;
   150	        }
   151	
   152	      next = ai.nodes;
   153	      for (i = 0; i < naddrs; i++)
   154	        {
   155	          hostent->h_addr_list[i] = (char*)&addrs[i];
   156	          memcpy(hostent->h_addr_list[i], &(((struct sockaddr_in6 *)next->ai_addr)->sin6_addr), sizeof(struct ares_in6_addr));
   157	          if (naddrttls)
   158	            {
   159	                if(next->ai_ttl > cname_ttl)
   160	                  addrttls[i].ttl = cname_ttl;
   161	                else
   162	                  addrttls[i].ttl = next->ai_ttl;
   163	
   164	                memcpy(&addrttls[i].ip6addr, &(((struct sockaddr_in6 *)next->ai_addr)->sin6_addr), sizeof(struct ares_in6_addr));
   165	            }
   166	          next = next->ai_next;
   167	        }
   168	    }
   169	
   170	  hostent->h_addr_list[naddrs] = NULL;
   171	
   172	  if (host)
   173	    {
   174	      *host = hostent;
   175	    }
   176	  else
   177	    {
   178	      ares_free_hostent(hostent);
   179	    }
   180	
   181	  if (naddrttls)
   182	    {
   183	      *naddrttls = naddrs;
   184	    }
   185	
   186	  ares__freeaddrinfo_cnames(ai.cnames);
   187	  ares__freeaddrinfo_nodes(ai.nodes);
   188	  return ARES_SUCCESS;
   189	
   190	enomem:
   191	  ares_free(aliases);
   192	  ares_free(hostent);
   193	  ares__freeaddrinfo_cnames(ai.cnames);
   194	  ares__freeaddrinfo_nodes(ai.nodes);
   195	  ares_free(question_hostname);
   196	  return ARES_ENOMEM;
   197	}
